int fd = 42;             // Existing file descriptor
typedef long long loff_t;
loff_t start = 0;
loff_t len = 4096;

// --- Advice Constants ---
#define FADV_NORMAL     0  // Default access pattern
#define FADV_RANDOM     1  // Expect random access
#define FADV_SEQUENTIAL 2  // Expect sequential access
#define FADV_WILLNEED   3  // Pre-fetch data
#define FADV_DONTNEED   4  // Release cached pages (cache drop)

// --- Usage Example 1: Sequential Read Optimization ---
int ret = arm_fadvise64_64(
    fd,
    FADV_SEQUENTIAL,
    start,
    len
);

// --- Usage Example 2: Releasing Cache (Until EOF) ---
// len == 0 advises until the end of the file.
loff_t len_eof = 0;
arm_fadvise64_64(fd, FADV_DONTNEED, start, len_eof);

// Common Error: Advising on a non-regular file (e.g., pipe/socket) returns ESPIPE.
// Check ret for failure (-1).
